  sources.push({ id: "livret-histoire-periodes", title: "Livret du citoyen — périodes et personnages (p. 38–47)", kind: "livret", theme: "history", section: "Histoire", url: "assets/livret-du-citoyen-mai-2026.pdf#page=38", facts: [] });
  sources.push({ id: "livret-histoire-fetes", title: "Livret du citoyen — fêtes et mémoire nationale (p. 57)", kind: "livret", theme: "history", section: "Culture et patrimoine", url: "assets/livret-du-citoyen-mai-2026.pdf#page=57", facts: [] });
